#!/usr/bin/env python3
"""Generates assets/catalog/platforms.json — the offline platform catalog seed.

Run:  python3 tool/gen_catalog.py
Fields per entry: id, name, categories, website, type, vendor, icon, description.
`icon` is a Simple Icons slug (CC0 brand glyph set) or null. A colored original
logo placed at assets/logos/<id>.(svg|png) always takes priority at runtime.
"""
