# (name, categories, website, type, vendor, simple-icon slug or None, description)
P = []
def add(name, cats, web, typ="service", vendor=None, icon=None, desc="", id=None):
    pid = id or re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-")
    P.append(dict(id=pid, name=name, categories=cats, website=web, type=typ,
                  vendor=vendor, icon=icon, description=desc))

